import { reactive, computed, App } from 'vue';

// 路由配置接口
export interface RouteConfig {
  path: string;
  name?: string;
  component: any;
  props?: boolean;
  meta?: Record<string, any>;
  /** 路由级前置守卫，返回 false 阻止路由更新 */
  beforeEnter?: (to: RouteLocation) => boolean | void;
}

// 当前路由状态接口
export interface RouteLocation {
  path: string;
  name?: string;
  query: Record<string, string>;
  params: Record<string, any>;
  meta?: Record<string, any>;
}

class CustomRouter {
  private routes: RouteConfig[] = [];
  /** 部署基础路径，从初始 URL 自动推导（如 /team6-base/dev/gs-viewer2/） */
  private base = '/';
  /** 标记是否正在执行 push/replace 内部导航，用于抑制 hashchange 回调 */
  private navigating = false;
  private currentRoute = reactive<RouteLocation>({
    path: '/',
    query: {},
    params: {},
    meta: {},
  });

  constructor(routes: RouteConfig[]) {
    this.routes = routes;
    this.detectBase();
    this.init();
  }

  /**
   * 从初始 URL 推导部署基础路径（每次实例化时纯函数式推导，不做缓存）
   *
   * v1.3.0 策略：base 一律归一化为以 `/index.html/` 结尾——把 index.html
   * 视为「SPA 入口分隔符」而非「HTML 文件名」。这样 push/replace 拼接
   * `base + routePath` 时自动带上 index.html，配合无 SPA fallback 的资源
   * 服务器（URL 到什么位置就找什么文件）也能强刷可达。
   *
   * 归一化后 base 形态：
   * - 根路径部署：`/index.html/`
   * - 子目录部署：`/team6-base/xxx/index.html/`
   *
   * v1.3.3：移除 sessionStorage 缓存。原缓存动机是「路由导航时避免重复推导出错」，
   * 但 detectBase 仅在构造函数中调用一次，且推导输入 `window.location.pathname`
   * 是幂等的——同一入口 URL 必然推出同一 base，缓存无正向价值；反而在用户手动
   * 改地址栏跨部署路径切换时（如从 /team6/ 改到 /）会读到残留旧值导致 parseUrl
   * 剥离 base 失败。改为每次纯函数式推导，去掉一处状态依赖。
   */
  private detectBase() {
    const { pathname } = window.location;
    let dir: string; // 归一化后的「目录前缀」，末尾必带 /

    // A) 已含 /index.html/ 段：/team6/index.html/viewer2 → dir=/team6/
    const indexHtmlSegIdx = pathname.indexOf('/index.html/');
    if (indexHtmlSegIdx >= 0) {
      dir = pathname.substring(0, indexHtmlSegIdx + 1);
    }
    // B) 恰好以 /index.html 结尾：/index.html 或 /subpath/index.html → dir=<所在目录>
    else if (pathname.endsWith('/index.html')) {
      dir = pathname.substring(0, pathname.lastIndexOf('/') + 1);
    }
    // C) 根路径或目录形态：/ 或 /team6/ → dir=<自身>
    else if (pathname === '/' || (pathname.endsWith('/') && pathname.indexOf('.') === -1)) {
      dir = pathname;
    }
    // D) 兜底：非入口页且不含 index.html 段（罕见），退回根目录
    else {
      dir = '/';
    }

    // 归一化：一律拼上 index.html/ 作为 SPA 入口分隔符
    this.base = `${dir}index.html/`;
  }

  // 获取当前路由（响应式）
  get route() {
    return computed(() => this.currentRoute);
  }

  // 获取当前组件
  get currentComponent() {
    return computed(() => {
      const route = this.findMatchingRoute(this.currentRoute.path);
      return route?.component || this.routes[0]?.component;
    });
  }

  // 编程式导航
  push(to: string | { path: string; query?: Record<string, any> }) {
    let routePath = '';
    let queryString = '';

    if (typeof to === 'string') {
      routePath = to;
    } else {
      routePath = to.path;
      if (to.query && Object.keys(to.query).length > 0) {
        queryString = `?${new URLSearchParams(to.query).toString()}`;
      }
    }

    // 先清掉 hash（避免 pushState 后 hash 残留，导致 parseUrl 优先读旧 hash）
    this.clearHash();
    // 组装完整 URL：base + routePath（去掉 routePath 开头的 / 避免双斜杠）
    const normalizedPath = routePath.startsWith('/') ? routePath.slice(1) : routePath;
    const fullUrl = this.base + normalizedPath + queryString;
    window.history.pushState({}, '', fullUrl);
    this.updateRoute();
  }

  // 替换当前路由
  replace(to: string | { path: string; query?: Record<string, any> }) {
    let routePath = '';
    let queryString = '';

    if (typeof to === 'string') {
      routePath = to;
    } else {
      routePath = to.path;
      if (to.query && Object.keys(to.query).length > 0) {
        queryString = `?${new URLSearchParams(to.query).toString()}`;
      }
    }

    this.clearHash();
    const normalizedPath = routePath.startsWith('/') ? routePath.slice(1) : routePath;
    const fullUrl = this.base + normalizedPath + queryString;
    window.history.replaceState({}, '', fullUrl);
    this.updateRoute();
  }

  /** 清除 hash，内部导航时抑制 hashchange 回调避免重复触发 updateRoute */
  private clearHash() {
    if (!window.location.hash) return;
    this.navigating = true;
    window.location.hash = '';
    this.navigating = false;
  }

  // 后退
  back() {
    window.history.back();
  }

  // 前进
  forward() {
    window.history.forward();
  }

  // 安装插件
  install(app: App) {
    // 提供全局路由实例
    app.config.globalProperties.$router = this;
    app.config.globalProperties.$route = this.route;

    // 提供注入
    app.provide('router', this);
    app.provide('route', this.route);
  }

  // 初始化路由器
  private init() {
    // 监听 popstate 事件（浏览器前进/后退）
    window.addEventListener('popstate', () => {
      this.updateRoute();
    });

    // 监听 hashchange 事件（支持 #/viewer2 格式的 hash 路由入口）
    window.addEventListener('hashchange', () => {
      if (this.navigating) return; // 内部导航时跳过
      this.updateRoute();
    });

    // v1.3.0：首帧静默把地址栏补齐为含 /index.html/ 的形态
    // 例如：/ → /index.html/ ；/team6/ → /team6/index.html/ ；/team6/index.html → /team6/index.html/
    // 若入口 URL 已含 /index.html/，则 pathname.startsWith(base) 为 true，跳过；
    // 若入口不含（根/目录/裸 index.html），走 replaceState 静默纠正。
    // 目的：让用户下次强刷时能命中 index.html 文件，避免地址栏与 push 后的形态割裂。
    this.rectifyInitialUrl();

    // 初始化当前路由
    this.updateRoute();
  }

  /**
   * 首屏地址栏纠正：把无 /index.html 的入口 URL 静默 replaceState 为归一化形态。
   * 仅在 hash 路由未启用（无 #/ hash）时执行，避免与 hash 兼容模式冲突。
   * 任意异常静默降级，不阻塞页面初始化。
   */
  private rectifyInitialUrl() {
    try {
      // hash 路由模式（如 #/viewer2 直接入口）不参与 pathname 纠正，交给 parseHash 处理
      const { hash } = window.location;
      if (hash?.startsWith('#/')) return;

      const currentPath = window.location.pathname;
      // 已符合归一化形态（含 /index.html/ 段）则无需纠正
      if (currentPath.startsWith(this.base)) return;
      // 恰好等于 base 去尾斜杠（如入口 http://host/xxx/index.html 且无后续路由）：
      // 用户明确要求「不在地址栏末尾补尾斜杠」，此处直接跳过 replaceState。
      // 首屏路由匹配由 parseUrl 兜底：pathname='/xxx/index.html' → routePath='/'（首页）。
      const baseNoTrailing = this.base.endsWith('/') ? this.base.slice(0, -1) : this.base;
      if (currentPath === baseNoTrailing) return;

      // 计算逻辑路径：把 currentPath 相对于「base 去掉 index.html/ 后的目录部分」剥离
      // 例：base=/team6/index.html/，currentPath=/team6/ → 剥离后为空 → 逻辑路径 '/'
      //     base=/index.html/，currentPath=/ → 剥离后为空 → 逻辑路径 '/'
      const baseDir = this.base.replace(/index\.html\/$/, ''); // 例：/team6/ 或 /
      let logicalPath = currentPath;
      if (baseDir !== '/' && currentPath.startsWith(baseDir)) {
        logicalPath = `/${currentPath.slice(baseDir.length)}`;
      } else if (baseDir === '/') {
        logicalPath = currentPath; // 已以 / 开头
      }
      if (!logicalPath.startsWith('/')) logicalPath = `/${logicalPath}`;

      // 拼装新 URL：base + logicalPath（去掉 logicalPath 开头的 / 避免双斜杠）
      const normalizedLogical = logicalPath.startsWith('/') ? logicalPath.slice(1) : logicalPath;
      const search = window.location.search || '';
      // v1.3.2：入口为"目录形态"（逻辑路径为空 = 首页）时，replaceState 目标去掉 base 的尾斜杠，
      // 避免出现 /xxx/index.html/ 这种末尾多一个斜杠的观感。
      // 仅在有后续路由段（logicalPath 非空）时才使用完整 base（保留尾斜杠拼接路由）。
      const targetBase = normalizedLogical === '' && this.base.endsWith('/') ? this.base.slice(0, -1) : this.base;
      const newUrl = targetBase + normalizedLogical + search;

      // 仅当新 URL 与当前不同才 replaceState，避免无谓的 history 抖动
      if (newUrl !== currentPath + search) {
        window.history.replaceState({}, '', newUrl);
      }
    } catch {
      /* 静默降级：replaceState 异常不阻塞初始化 */
    }
  }

  // 解析 URL 获取路由路径和查询参数（自动剥离部署基础路径）
  private parseUrl(url: string = window.location.pathname + window.location.search) {
    // Hash 兼容：如果 URL 中带有 #/ 开头的 hash，优先从 hash 解析路由
    const { hash } = window.location;
    if (hash?.startsWith('#/')) {
      return this.parseHash(hash);
    }

    let pathname: string;
    let search: string;
    const queryIndex = url.indexOf('?');
    if (queryIndex >= 0) {
      pathname = url.substring(0, queryIndex);
      search = url.substring(queryIndex + 1);
    } else {
      pathname = url;
      search = '';
    }

    // 剥离基础路径，得到路由路径（如 /viewer2）
    // v1.3.0 后 base 一定以 /index.html/ 结尾，此处一次剥净即可拿到逻辑路径
    let routePath = pathname;
    if (this.base !== '/' && pathname.startsWith(this.base)) {
      routePath = `/${pathname.slice(this.base.length)}`;
    } else if (this.base !== '/' && this.base.endsWith('/') && pathname === this.base.slice(0, -1)) {
      // v1.3.1：pathname 恰好等于 base 去尾斜杠（如入口 /xxx/index.html 无尾斜杠、无后续路由）
      // 视为首页访问，routePath 归一化为 '/'。此路径不 replaceState 补斜杠（用户策略）
      routePath = '/';
    }
    // 兜底：detectBase 缓存丢失或异常时 base 可能退化为 '/'，此时需剥掉残留 /index.html/ 前缀
    // 也用于容错场景：外部拼错 URL 未走 base 而带上了 /index.html/
    if (routePath.startsWith('/index.html/')) {
      routePath = routePath.substring('/index.html'.length); // 保留后续的 /viewer2
    } else if (routePath === '/index.html') {
      routePath = '/';
    }
    // 确保首页路径规范化
    if (!routePath || routePath === '') {
      routePath = '/';
    }

    const query: Record<string, string> = {};
    if (search) {
      const params = new URLSearchParams(search);
      params.forEach((value, key) => {
        query[key] = value;
      });
    }

    return { pathname: routePath, query };
  }

  /** 从 hash fragment 解析路由路径和查询参数（用于 #/viewer2 格式的 hash 路由入口） */
  private parseHash(hash: string) {
    const hashPath = hash.slice(1); // 去掉 #
    let pathname: string;
    let search: string;
    const queryIndex = hashPath.indexOf('?');
    if (queryIndex >= 0) {
      pathname = hashPath.substring(0, queryIndex);
      search = hashPath.substring(queryIndex + 1);
    } else {
      pathname = hashPath;
      search = '';
    }

    if (!pathname || pathname === '/') {
      pathname = '/';
    }

    const query: Record<string, string> = {};
    if (search) {
      const params = new URLSearchParams(search);
      params.forEach((value, key) => {
        query[key] = value;
      });
    }

    return { pathname, query };
  }

  // 查找匹配的路由（支持通配符前缀匹配）
  private findMatchingRoute(pathname: string): RouteConfig | undefined {
    // 1. 精确匹配
    let route = this.routes.find((r) => r.path === pathname);
    if (route) return route;

    // 2. 通配符前缀匹配（path 以 '/*' 结尾时匹配所有以该前缀开头的路径）
    route = this.routes.find((r) => {
      if (r.path.endsWith('/*')) {
        const prefix = r.path.slice(0, -2);
        return pathname.startsWith(prefix);
      }
      return false;
    });
    if (route) return route;

    // 3. 兜底：返回首页路由
    return this.routes[0];
  }

  // 更新当前路由状态
  private updateRoute() {
    const { pathname, query } = this.parseUrl();

    // 查找匹配的路由
    const route = this.findMatchingRoute(pathname);

    // 路由级守卫 beforeEnter
    if (route?.beforeEnter) {
      const routeLocation: RouteLocation = {
        path: pathname,
        name: route.name,
        query,
        params: route.props ? query : {},
        meta: route.meta || {},
      };
      const result = route.beforeEnter(routeLocation);
      // 返回 false 阻止路由状态更新（常用于外部跳转场景）
      if (result === false) return;
    }

    this.currentRoute.path = pathname;
    this.currentRoute.name = route?.name;
    this.currentRoute.query = query;
    this.currentRoute.params = route?.props ? query : {};
    this.currentRoute.meta = route?.meta || {};

    // 更新页面 meta 信息
    this.updateDocumentMeta(route?.meta);
  }

  // 更新页面 SEO meta 信息
  private updateDocumentMeta(meta?: Record<string, any>) {
    if (!meta) return;

    // 更新标题
    if (meta.title) {
      document.title = meta.title;

      // 更新 OG title
      const ogTitle = document.querySelector('meta[property="og:title"]');
      if (ogTitle) {
        ogTitle.setAttribute('content', meta.title);
      }

      // 更新 Twitter title
      const twitterTitle = document.querySelector('meta[name="twitter:title"]');
      if (twitterTitle) {
        twitterTitle.setAttribute('content', meta.title);
      }
    }

    // 更新 description
    if (meta.description) {
      const descMeta = document.querySelector('meta[name="description"]');
      if (descMeta) {
        descMeta.setAttribute('content', meta.description);
      }

      // 更新 OG description
      const ogDesc = document.querySelector('meta[property="og:description"]');
      if (ogDesc) {
        ogDesc.setAttribute('content', meta.description);
      }

      // 更新 Twitter description
      const twitterDesc = document.querySelector('meta[name="twitter:description"]');
      if (twitterDesc) {
        twitterDesc.setAttribute('content', meta.description);
      }
    }

    // 更新 keywords
    if (meta.keywords) {
      const keywordsMeta = document.querySelector('meta[name="keywords"]');
      if (keywordsMeta) {
        keywordsMeta.setAttribute('content', meta.keywords);
      }
    }
  }
}

// 创建路由器实例
export function createCustomRouter(routes: RouteConfig[]) {
  return new CustomRouter(routes);
}

export default CustomRouter;
