import { createCustomRouter, RouteConfig } from './custom-router';

/**
 * 根据当前页面 URL 推断 editor 子应用的基础路径。
 * 例如当前页面为 https://res.cymini.qq.com/team6-base/dev/gs-viewer2/index.html
 * 则 editor base 为 https://res.cymini.qq.com/team6-base/dev/gs-viewer2/editor
 *
 * 注意：不能用 pathname.replace(/\/[^/]*$/, '') 来推导 dir。
 * hash 模式下 pathname 始终是 SPA 入口页路径（如 /index.html），该算法正确；
 * 但迁移到 History API 后，pathname 可能是 /editor/splat-studio/xxx，
 * dir 会变为 /editor/splat-studio，导致 targetUrl 出现两层 editor 目录。
 * 因此改用 __router_base__（CustomRouter.detectBase 缓存的 SPA 部署根路径）。
 */
function getEditorBaseUrl(): string {
  const { origin } = window.location;
  let base = '/';
  try {
    const cached = sessionStorage.getItem('__router_base__');
    if (cached) base = cached;
  } catch { /* 无痕模式等环境下 sessionStorage 不可用 */ }
  return `${origin}${base}editor`;
}

/**
 * 跳转到 editor 子应用页面。
 * 自动检测死循环：当跳转目标的 pathname 仍以 /editor/ 开头时（如 localhost 环境），
 * 说明 editor 未独立部署，再次跳转会命中同一条通配符路由 → 阻止跳转。
 */
function redirectToEditor(editorName: string): boolean {
  const targetUrl = `${getEditorBaseUrl()}/${editorName}/index.html`;
  console.log(`Redirecting to ${targetUrl}`);

  try {
    const targetPath = new URL(targetUrl).pathname;
    if (targetPath.startsWith('/editor/')) {
      console.warn(
        `[Router] Editor "${editorName}" 跳转已阻止：目标 URL 仍在 SPA 路由范围内，会导致死循环。` +
        `（生产环境 editor 部署在子路径下，此检查不会误触发）`,
      );
      return false;
    }
  } catch { /* URL 解析失败，跳过 */ }

  window.location.href = targetUrl;
  return false;
}

const routes: RouteConfig[] = [
  {
    path: '/',
    name: 'ModelList',
    component: () => import('../pages/ModelList.vue'),
    meta: { title: 'Web Wide World' },
  },
  {
    path: '/viewer2',
    name: 'viewer2',
    component: () => import('../pages/scene-viewer/SceneViewer.vue'),
    props: true,
  },
  {
    path: '/debug-viewer',
    name: 'debugViewer',
    component: () => import('../pages/scene-viewer/DebugSceneViewer.vue'),
    meta: { title: 'Debug Scene Viewer' },
    props: true,
  },
  {
    path: '/creative',
    name: 'creativeViewer',
    component: () => import('../pages/creative-viewer/CreativeViewer.vue'),
    meta: { title: 'Creative Mode Test' },
  },
  // Editor 子应用跳转：重定向到 COS 上独立部署的页面
  {
    path: '/editor/navigator/*',
    name: 'editorNavigator',
    beforeEnter: () => redirectToEditor('navigator'),
    component: { render: () => null },
  },
  {
    path: '/editor/splat-studio/*',
    name: 'editorSplatStudio',
    beforeEnter: () => redirectToEditor('splat-studio'),
    component: { render: () => null },
  },
  {
    path: '/editor/file-converter/*',
    name: 'editorFileConverter',
    beforeEnter: () => redirectToEditor('file-converter'),
    component: { render: () => null },
  },
  {
    path: '/editor/meta-editor/*',
    name: 'editorMetaEditor',
    beforeEnter: () => redirectToEditor('meta-editor'),
    component: { render: () => null },
  },
  {
    path: '/editor/map-editor/*',
    name: 'editorMapEditor',
    beforeEnter: () => redirectToEditor('map-editor'),
    component: { render: () => null },
  },
  {
    path: '/editor/character-editor/*',
    name: 'editorCharacterEditor',
    beforeEnter: () => redirectToEditor('character-editor'),
    component: { render: () => null },
  },
];

const router = createCustomRouter(routes);

// 导出路由组件
export { default as RouterView } from './RouterView.vue';
export { default as RouterLink } from './RouterLink.vue';

export default router;
